// Ampliación del catálogo (21/10/2026): términos nuevos de los datos, familias de calibre nuevas o ampliadas
// y el resumen de cada reloj añadido, en los cinco idiomas. Se mezcla con cada diccionario en index.ts.
import type { CalibreKey, Terms } from './types';
import type { Lang } from './langs';

type Cal = { nombre: string; fabricante: string; resumen: string; texto: string[]; paraQuien: string };
type Extra = { terms: Partial<Record<keyof Terms, Record<string, string>>>; calibres: Partial<Record<CalibreKey, Cal>>; resumen: Record<string, string> };

