    calibres: {
      'sellita-sw200': { nombre: 'ETA 2824-2, 2836-2 und Sellita SW200-1', fabricante: 'ETA und Sellita', resumen: 'Das meistverbaute Schweizer Automatikwerk: 25 oder 26 Steine, 28.800 Halbschwingungen pro Stunde und rund 38 Stunden.', texto: ['Das ETA 2824-2 ist seit den Siebzigern das Schweizer Referenz-Automatikwerk, und das Sellita SW200-1 übernimmt seine Architektur, seit das Patent ausgelaufen ist. Das 2836-2 ist die ETA-Version mit Tag und Datum. Sie arbeiten mit 28.800 Halbschwingungen pro Stunde, bieten rund 38 Stunden Gangreserve, Sekundenstopp und Handaufzug.', 'Viele Marken geben ihnen eigene Namen: Glycine GL224, Alpina AL-525, Frederique Constant FC-303, Laco 24 oder Junghans J800.1. Sie sind robust und jeder Uhrmacher kennt sie, aber ihre Gangreserve ist nur halb so lang wie die eines Powermatic 80.'], paraQuien: 'Für alle, die eine leicht zu wartende Schweizer Uhr wollen und nicht mehr als anderthalb Tage Gangreserve brauchen.' },
      'miyota-821': { nombre: 'Miyota 82er-Serie (821A, 8215 und 82S0)', fabricante: 'Miyota (Citizen)', resumen: 'Die verbreitetsten japanischen Automatikwerke außerhalb von Seiko: einfach, zuverlässig und mit rund 42 Stunden.', texto: ['Miyota, die Citizen-Tochter, die Werke an andere Marken verkauft, baut die 82er-Serie seit den Achtzigern. Laut ihren Datenblättern arbeitet sie mit 21.600 Halbschwingungen pro Stunde und rund 42 Stunden Gangreserve. Laco nutzt sie als Basis des Laco 2S (früher des Laco 21 auf dem 821A); Timex und Bulova verbauen sie unter ihrem eigenen Namen.', 'Aktuelle Versionen wie das 8215 und das 82S0 haben Handaufzug und Sekundenstopp; das alte 821A hatte keinen Sekundenstopp. Beim 82S0 sieht man die Unruh durch ein Fenster im Zifferblatt. Es sind einfache Werke, die jede Werkstatt reparieren kann.'], paraQuien: 'Für alle, die eine zuverlässige, günstig zu wartende Automatikuhr ohne Luxusfinish wollen.' },
      'citizen-82': { nombre: 'Citizen 82er-Serie (8200, 8203, 8204 und 8210)', fabricante: 'Citizen (Miyota)', resumen: 'Citizens Automatikwerke aus der Tochter Miyota: 21 Steine und rund 40 Stunden.', texto: ['Die 82er-Serie ist Citizens Einstiegs-Automatikwerk, gefertigt von Miyota, der Tochter, die auch andere Marken beliefert. Es arbeitet mit 21.600 Halbschwingungen pro Stunde bei rund 40 bis 42 Stunden Gangreserve.', 'Die Versionen unterscheiden sich in einem wichtigen Detail: Das 8200 hat weder Sekundenstopp noch Handaufzug, das 8203 nur Handaufzug, das 8204 und das 8210 beides. Deshalb sind zwei Citizen, die gleich aussehen, innen nicht gleich.'], paraQuien: 'Für alle, die eine robuste Citizen-Automatikuhr wollen und prüfen, welche Version des Kalibers drinsteckt.' },
      'orient-f6': { nombre: 'Orient F6 (F6922, F6724, F6B24 und F6N47)', fabricante: 'Orient (Seiko Epson)', resumen: 'Orients eigene Automatikwerke: 22 Steine, 40 bis 50 Stunden, Sekundenstopp und Handaufzug.', texto: ['Orient fertigt seine Kaliber selbst innerhalb der Seiko-Epson-Gruppe. Die F6-Familie hat vor einigen Jahren die alten Werke ohne Sekundenstopp abgelöst und steckt heute in fast der ganzen Kollektion: Bambino, Mako, Kamasu und die Orient-Star-Modelle.', 'Sie arbeiten mit 21.600 Halbschwingungen pro Stunde bei rund 40 Stunden Gangreserve. Das F6922 zeigt Tag und Datum, das F6724 nur das Datum, das F6B24 ergänzt die Sonne-Mond-Anzeige der Bambino Sun & Moon. Das F6N47 der Orient-Star-Linie bietet 50 Stunden und eine Gangreserveanzeige auf dem Zifferblatt.'], paraQuien: 'Für alle, die ein Manufakturkaliber für wenig Geld suchen und Wert darauf legen, dass die Marke es selbst baut.' },
      'seiko-7s26': { nombre: 'Seiko 7S26', fabricante: 'Seiko', resumen: 'Das altgediente Automatikwerk der Seiko 5: einfach, langlebig und ohne Sekundenstopp oder Handaufzug.', texto: ['Das 7S26 war über zwanzig Jahre das Kaliber der Seiko 5 und der legendären SKX007. Es hat 21 Steine, arbeitet mit 21.600 Halbschwingungen pro Stunde und bietet rund 41 Stunden Gangreserve.', 'Es ist ein sehr einfaches Kaliber: Es hat keinen Sekundenstopp und lässt sich nicht von Hand aufziehen; bleibt es stehen, muss man die Uhr bewegen, damit sie anläuft. Dafür ist es fast unverwüstlich und günstig in der Revision. Das 4R36 ist sein direkter Nachfolger und ergänzt beide Funktionen.'], paraQuien: 'Für alle, die eine kleine, günstige Automatikuhr wollen und sie nicht sekundengenau stellen müssen.' },
      'citizen-90': { nombre: 'Citizen 9051 und 9054', fabricante: 'Citizen', resumen: 'Citizens Automatikwerke mit 28.800 Halbschwingungen: Sekundenstopp, Handaufzug und rund 42 Stunden.', texto: ['Die 905x-Familie ist Citizens Automatikwerk der Mittelklasse und steckt in der Promaster Fujitsubo und den sportlicheren Series-8-Modellen. Es arbeitet mit 28.800 Halbschwingungen pro Stunde, der Sekundenzeiger macht also acht Schritte pro Sekunde, und bietet rund 42 Stunden Gangreserve.', 'Das 9051 zeigt das Datum, das 9054 ergänzt einen GMT-Zeiger für eine zweite Zeitzone. Beide haben Sekundenstopp und Handaufzug.'], paraQuien: 'Für alle, die die hohe Frequenz eines klassischen Schweizer Werks in einer japanischen Uhr wollen.' },
      'eta-2892': { nombre: 'ETA 2892-A2', fabricante: 'ETA, Swatch Group', resumen: 'Das flache Schweizer Automatikwerk schlechthin: rund 3,6 mm hoch, 28.800 Halbschwingungen pro Stunde und rund 42 Stunden.', texto: ['Das 2892-A2 gehört zu den flachsten in Serie gefertigten Automatikwerken: Es ist rund 3,6 mm hoch. Deshalb ist es die Basis vieler flacher eleganter Uhren wie der Hamilton Jazzmaster Thinline oder der Mido Baroncelli Heritage, die Mido 1192 nennt.', 'Es arbeitet mit 28.800 Halbschwingungen pro Stunde, bietet rund 42 Stunden Gangreserve, Sekundenstopp und Handaufzug. Es ist teurer als das 2824-2 und steckt daher vor allem in eleganten Uhren.'], paraQuien: 'Für alle, die eine sehr flache elegante Uhr wollen, die unter jede Manschette passt.' },
      sistem51: { nombre: 'Swatch Sistem51', fabricante: 'Swatch', resumen: 'Ein Schweizer Automatikwerk aus 51 Teilen, von Maschinen montiert, mit rund 90 Stunden Gangreserve.', texto: ['Das Sistem51 heißt so, weil es aus 51 Teilen besteht, viel weniger als ein normales Automatikwerk, und vollständig von Maschinen montiert wird. Dadurch ist es das günstigste Schweizer Automatikwerk im Katalog und das mit der meisten Gangreserve: rund 90 Stunden.', 'Dafür ist es versiegelt: Es lässt sich weder öffnen noch revidieren, bei einem Defekt wird die Uhr ersetzt. Es hat auch keinen Sekundenstopp und keinen Handaufzug; die Krone dient nur zum Stellen.'], paraQuien: 'Für alle, die eine Schweizer Design-Automatikuhr für rund 200 € wollen und akzeptieren, dass sie nicht reparierbar ist.' },
      'vostok-2416': { nombre: 'Vostok 2416B', fabricante: 'Vostok', resumen: 'Das russische Kaliber der Amphibia: 31 Steine, 19.800 Halbschwingungen pro Stunde und Handaufzug.', texto: ['Das 2416B ist ein Manufakturkaliber, das Vostok seit den Achtzigern in Tschistopol baut. Es arbeitet mit 19.800 Halbschwingungen pro Stunde, etwas weniger als fast alle anderen im Katalog, und bietet rund 31 Stunden Gangreserve.', 'Es lässt sich von Hand aufziehen, hat aber keinen Sekundenstopp. Die Verarbeitung ist rau und die Genauigkeit mäßig, aber es ist sehr robust und gehört zum Charme der Amphibia.'], paraQuien: 'Für alle, die eine Taucheruhr mit Geschichte und eigenem Kaliber für rund 200 € suchen.' },
    },
