    calibres: {
      'sellita-sw200': { nombre: 'ETA 2824-2, 2836-2 e Sellita SW200-1', fabricante: 'ETA e Sellita', resumen: 'L’automatico svizzero più diffuso: 25 o 26 rubini, 28.800 alternanze all’ora e circa 38 ore.', texto: ['L’ETA 2824-2 è l’automatico svizzero di riferimento dagli anni Settanta, e il Sellita SW200-1 ne riprende l’architettura da quando il brevetto è scaduto. Il 2836-2 è la versione ETA con giorno e data. Lavorano a 28.800 alternanze all’ora, offrono circa 38 ore di riserva, stop secondi e carica manuale.', 'Molti marchi danno loro un nome proprio: Glycine GL224, Alpina AL-525, Frederique Constant FC-303, Laco 24 o Junghans J800.1. Sono robusti e ogni orologiaio li conosce, ma la loro riserva è la metà di quella di un Powermatic 80.'], paraQuien: 'Per chi vuole uno svizzero semplice da mantenere e non ha bisogno di più di un giorno e mezzo di riserva.' },
      'miyota-821': { nombre: 'Miyota serie 82 (821A, 8215 e 82S0)', fabricante: 'Miyota (Citizen)', resumen: 'Gli automatici giapponesi più diffusi fuori da Seiko: semplici, affidabili e con circa 42 ore.', texto: ['Miyota, la controllata di Citizen che vende calibri ad altri marchi, produce la serie 82 dagli anni Ottanta. Secondo le sue schede lavora a 21.600 alternanze all’ora con circa 42 ore di riserva. Laco la usa come base del suo Laco 2S (prima del Laco 21 sull’821A); Timex e Bulova la montano con il suo nome originale.', 'Le versioni attuali come l’8215 e l’82S0 hanno carica manuale e stop secondi; il vecchio 821A non aveva lo stop secondi. L’82S0 mostra il bilanciere da una finestra nel quadrante. Sono calibri semplici che qualsiasi orologiaio sa riparare.'], paraQuien: 'Per chi vuole un automatico affidabile ed economico da mantenere, senza finiture di lusso.' },
      'citizen-82': { nombre: 'Citizen serie 82 (8200, 8203, 8204 e 8210)', fabricante: 'Citizen (Miyota)', resumen: 'Gli automatici di Citizen prodotti dalla controllata Miyota: 21 rubini e circa 40 ore.', texto: ['La serie 82 è l’automatico d’ingresso di Citizen, prodotto da Miyota, la controllata che vende calibri anche ad altri marchi. Lavora a 21.600 alternanze all’ora con circa 40-42 ore di riserva.', 'Le versioni differiscono in un dettaglio importante: l’8200 non ha né stop secondi né carica manuale; l’8203 ha la carica manuale ma non lo stop secondi; l’8204 e l’8210 hanno entrambi. Per questo due Citizen che sembrano uguali non lo sono dentro.'], paraQuien: 'Per chi vuole un Citizen automatico robusto e controlla quale versione del calibro monta.' },
      'orient-f6': { nombre: 'Orient F6 (F6922, F6724, F6B24 e F6N47)', fabricante: 'Orient (Seiko Epson)', resumen: 'Gli automatici di manifattura di Orient: 22 rubini, da 40 a 50 ore, stop secondi e carica manuale.', texto: ['Orient produce i propri calibri all’interno del gruppo Seiko Epson. La famiglia F6 ha sostituito qualche anno fa i vecchi calibri senza stop secondi e oggi equipaggia quasi tutta la gamma: il Bambino, il Mako, il Kamasu e gli Orient Star.', 'Lavorano a 21.600 alternanze all’ora con circa 40 ore di riserva. L’F6922 mostra giorno e data; l’F6724 solo la data; l’F6B24 aggiunge l’indicatore sole e luna del Bambino Sun & Moon. L’F6N47 della gamma Orient Star sale a 50 ore e ha un indicatore della riserva sul quadrante.'], paraQuien: 'Per chi cerca un calibro di manifattura a poco prezzo e apprezza un marchio che produce il proprio movimento.' },
      'seiko-7s26': { nombre: 'Seiko 7S26', fabricante: 'Seiko', resumen: 'L’automatico storico dei Seiko 5: semplice, duraturo, senza stop secondi né carica manuale.', texto: ['Per oltre vent’anni il 7S26 ha equipaggiato i Seiko 5 e il leggendario SKX007. Ha 21 rubini, lavora a 21.600 alternanze all’ora e offre circa 41 ore di riserva.', 'È un calibro molto essenziale: non ha lo stop secondi e non si carica a mano, quindi se si ferma bisogna muoverlo per farlo ripartire. In cambio è quasi indistruttibile ed economico da revisionare. Il 4R36 è il suo successore diretto e aggiunge entrambe le funzioni.'], paraQuien: 'Per chi vuole un automatico piccolo ed economico e non ha bisogno di regolarlo al secondo.' },
      'citizen-90': { nombre: 'Citizen 9051 e 9054', fabricante: 'Citizen', resumen: 'Gli automatici Citizen a 28.800 alternanze: stop secondi, carica manuale e circa 42 ore.', texto: ['La famiglia 905x è l’automatico di fascia media di Citizen, quello del Promaster Fujitsubo e delle Series 8 più sportive. Lavora a 28.800 alternanze all’ora, quindi la lancetta dei secondi avanza otto volte al secondo, e offre circa 42 ore di riserva.', 'Il 9051 mostra la data; il 9054 aggiunge una lancetta GMT per leggere un secondo fuso orario. Entrambi hanno stop secondi e carica manuale.'], paraQuien: 'Per chi vuole l’alta frequenza di un classico calibro svizzero in un orologio giapponese.' },
      'eta-2892': { nombre: 'ETA 2892-A2', fabricante: 'ETA, Swatch Group', resumen: 'L’automatico svizzero sottile per eccellenza: circa 3,6 mm di altezza, 28.800 alternanze all’ora e circa 42 ore.', texto: ['Il 2892-A2 è uno dei calibri automatici di serie più sottili: è alto circa 3,6 mm. Per questo è la base di molti orologi eleganti sottili, come l’Hamilton Jazzmaster Thinline o il Mido Baroncelli Heritage, che Mido chiama 1192.', 'Lavora a 28.800 alternanze all’ora, offre circa 42 ore di riserva, stop secondi e carica manuale. Costa più del 2824-2, e per questo compare soprattutto negli orologi eleganti.'], paraQuien: 'Per chi vuole un orologio elegante molto sottile che scivoli sotto qualsiasi polsino.' },
      sistem51: { nombre: 'Swatch Sistem51', fabricante: 'Swatch', resumen: 'Un automatico svizzero di 51 componenti assemblato da macchine, con circa 90 ore di riserva.', texto: ['Il Sistem51 si chiama così perché ha 51 componenti, molti meno di un automatico normale, ed è assemblato interamente da macchine. Per questo è l’automatico svizzero più economico del catalogo e quello con più riserva: circa 90 ore.', 'In cambio è sigillato: non si può aprire né revisionare, e se si guasta si sostituisce l’orologio. Non ha nemmeno stop secondi né carica manuale; la corona serve solo a regolare l’ora.'], paraQuien: 'Per chi vuole un automatico svizzero di design a circa 200 € e accetta che non si ripari.' },
      'vostok-2416': { nombre: 'Vostok 2416B', fabricante: 'Vostok', resumen: 'Il calibro russo degli Amphibia: 31 rubini, 19.800 alternanze all’ora e carica manuale.', texto: ['Il 2416B è un calibro di manifattura che Vostok produce a Čistopol dagli anni Ottanta. Lavora a 19.800 alternanze all’ora, un po’ meno di quasi tutti gli altri del catalogo, e offre circa 31 ore di riserva.', 'Si carica a mano ma non ha lo stop secondi. Ha finiture grezze e una precisione modesta, ma è molto resistente e fa parte del fascino degli Amphibia.'], paraQuien: 'Per chi vuole un subacqueo con una storia e un calibro di manifattura a circa 200 €.' },
    },
